x=np.linspace(30,220,600);pdf=stats.lognorm.pdf(x,s=.25,scale=100*np.exp((.10-.5*.25**2)));ax.plot(x,pdf,color=ACCENT);ax.fill_between(x,pdf,where=x>=130,color=GOOD,alpha=.22,label='above $130');ax.fill_between(x,pdf,where=x<=70,color=BAD,alpha=.22,label='below $70');ax.axvline(100,color=MUTED,ls='--');ax.set_xlabel('Terminal price (USD/share)');ax.set_ylabel('Density');ax.set_title('Price distribution is positive and skewed',loc='left');ax.legend()
